1	#!/usr/bin/env node
2	// create-test.mjs — Test Factory 开工命令。
3	//
4	// 用法：
5	//   node factory/create-test.mjs <brief.json>
6	//   node factory/create-test.mjs factory/examples/example-brief.json
7	//
8	// 职责（有意保持最小）：
9	//   1. 按 factory/brief.schema.json 校验 brief（内置 draft-07 子集校验器，零依赖）
10	//   2. 附加语义校验：product_id 唯一性 / 防覆盖 / custom-lite profile 硬约束
11	//   3. 创建标准工作目录 factory/work/<product_id>/，写入各阶段任务文件骨架
12	//   4. 打印下一步操作说明，交给后续 agent 按固定协议继续生产
13	//
14	// 不调用模型 API，不生成任何内容；未完成处一律写 TODO / null，不假造结果。
15	
16	import { readFileSync, writeFileSync, existsSync, mkdirSync, readdirSync } from "node:fs";
17	import { join, resolve, dirname } from "node:path";
18	import { fileURLToPath } from "node:url";
19	
20	const FACTORY = dirname(fileURLToPath(import.meta.url));
21	const REPO = resolve(FACTORY, "..");
22	const WORK_DIR = join(FACTORY, "work");
23	const PRODUCTS_DIR = join(REPO, "server", "content", "products");
24	
25	const FAIL = (msg) => {
26	  console.error(`✗ ${msg}`);
27	  process.exit(1);
28	};
29	const TODO = "TODO（未完成，禁止假造；完成后删除此标记并填写依据）";
30	
31	/* ---------------------------------------------------------------- validator */
32	// 支持 draft-07 子集：type(含数组)/required/properties/additionalProperties/
33	// enum/pattern/minLength/maxLength/minimum/maximum/items/minItems/maxItems
34	function matchType(t, v) {
35	  switch (t) {
36	    case "string": return typeof v === "string";
37	    case "integer": return Number.isInteger(v);
38	    case "number": return typeof v === "number" && Number.isFinite(v);
39	    case "boolean": return typeof v === "boolean";
40	    case "array": return Array.isArray(v);
41	    case "object": return v !== null && typeof v === "object" && !Array.isArray(v);
42	    case "null": return v === null;
43	    default: return false;
44	  }
45	}
46	function describe(v) {
47	  if (v === null) return "null";
48	  if (Array.isArray(v)) return "array";
49	  return typeof v;
50	}
51	function validateNode(schema, value, path, errs) {
52	  const types = Array.isArray(schema.type) ? schema.type : [schema.type].filter(Boolean);
53	  if (types.length && !types.some((t) => matchType(t, value))) {
54	    errs.push(`${path}: 期望类型 ${types.join("|")}，实际 ${describe(value)}`);
55	    return;
56	  }
57	  if (schema.enum && !schema.enum.includes(value)) {
58	    errs.push(`${path}: 必须是 ${schema.enum.join(" / ")}，实际 ${JSON.stringify(value)}`);
59	  }
60	  if (typeof value === "string") {
61	    if (schema.minLength != null && value.length < schema.minLength)
62	      errs.push(`${path}: 长度 ${value.length} < minLength ${schema.minLength}`);
63	    if (schema.maxLength != null && value.length > schema.maxLength)
64	      errs.push(`${path}: 长度 ${value.length} > maxLength ${schema.maxLength}`);
65	    if (schema.pattern && !new RegExp(schema.pattern).test(value))
66	      errs.push(`${path}: "${value}" 不匹配 /${schema.pattern}/`);
67	  }
68	  if (typeof value === "number") {
69	    if (schema.minimum != null && value < schema.minimum)
70	      errs.push(`${path}: ${value} < minimum ${schema.minimum}`);
71	    if (schema.maximum != null && value > schema.maximum)
72	      errs.push(`${path}: ${value} > maximum ${schema.maximum}`);
73	  }
74	  if (Array.isArray(value)) {
75	    if (schema.minItems != null && value.length < schema.minItems)
76	      errs.push(`${path}: ${value.length} 项 < minItems ${schema.minItems}`);
77	    if (schema.maxItems != null && value.length > schema.maxItems)
78	      errs.push(`${path}: ${value.length} 项 > maxItems ${schema.maxItems}`);
79	    if (schema.items) value.forEach((v, i) => validateNode(schema.items, v, `${path}[${i}]`, errs));
80	  }
81	  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
82	    for (const req of schema.required ?? []) {
83	      if (!(req in value)) errs.push(`${path}: 缺少必填字段 "${req}"`);
84	    }
85	    for (const [k, v] of Object.entries(value)) {
86	      const ps = schema.properties?.[k];
87	      if (ps) validateNode(ps, v, `${path}.${k}`, errs);
88	      else if (schema.additionalProperties === false)
89	        errs.push(`${path}: 未知字段 "${k}"（schema additionalProperties=false）`);
90	    }
91	  }
92	}
93	const validateBrief = (schema, brief) => {
94	  const errs = [];
95	  validateNode(schema, brief, "brief", errs);
96	  return errs;
97	};
98	
99	/* ------------------------------------------------------------- load & check */
100	const argv = process.argv.slice(2);
101	const CHECK_ONLY = argv[0] === "--check";
102	const [briefArg] = CHECK_ONLY ? argv.slice(1) : argv;
103	if (!briefArg) {
104	  console.log("用法: node factory/create-test.mjs [--check] <brief.json>");
105	  console.log("示例: node factory/create-test.mjs factory/examples/example-brief.json");
106	  console.log("      node factory/create-test.mjs --check factory/examples/reconstructed-greek_goddess-brief.json");
107	  process.exit(1);
108	}
109	const briefPath = resolve(briefArg);
110	if (!existsSync(briefPath)) FAIL(`brief 文件不存在: ${briefPath}`);
111	
112	let brief;
113	try {
114	  brief = JSON.parse(readFileSync(briefPath, "utf8"));
115	} catch (e) {
116	  FAIL(`brief 不是合法 JSON: ${e.message}`);
117	}
118	const schema = JSON.parse(readFileSync(join(FACTORY, "brief.schema.json"), "utf8"));
119	const errors = validateBrief(schema, brief);
120	if (errors.length) {
121	  console.error(`✗ brief 未通过 schema 校验（${errors.length} 项）：`);
122	  for (const e of errors) console.error(`  - ${e}`);
123	  process.exit(1);
124	}
125	
126	const { product_id, commercial_mode } = brief;
127	const warnings = [];
128	
129	// --check 模式：只校验（schema + 在售产品冲突信息），不创建任何目录
130	if (CHECK_ONLY) {
131	  let clashNote = "无";
132	  if (existsSync(PRODUCTS_DIR)) {
133	    const clash = readdirSync(PRODUCTS_DIR).find(
134	      (d) => d.toLowerCase() === product_id.toLowerCase()
135	    );
136	    if (clash) clashNote = `有（server/content/products/${clash}，在售产品）`;
137	  }
138	  console.log(`✓ schema 校验通过: ${briefPath}`);
139	  console.log(`  product_id=${product_id} · commercial_mode=${commercial_mode} · 与在售产品冲突: ${clashNote}`);
140	  process.exit(0);
141	}
142	
143	// 1) product_id 不得与在售产品目录冲突（绝不覆盖已有产品）
144	const RESERVED = new Set(["work", "examples", "profiles", "skills", "creators", "templates"]);
145	if (RESERVED.has(product_id)) FAIL(`product_id "${product_id}" 是工厂保留名，请更换。`);
146	if (existsSync(PRODUCTS_DIR)) {
147	  const clash = readdirSync(PRODUCTS_DIR).find(
148	    (d) => d.toLowerCase() === product_id.toLowerCase()
149	  );
150	  if (clash) FAIL(`product_id "${product_id}" 与在售产品目录 server/content/products/${clash} 冲突。不允许覆盖已有产品，请更换 ID。`);
151	}
152	
153	// 2) 防覆盖：工作目录已存在则拒绝
154	const workDir = join(WORK_DIR, product_id);
155	if (existsSync(workDir)) {
156	  FAIL(`工作目录已存在: factory/work/${product_id}（防覆盖，不重跑。如需重开请手动归档旧目录后改名）`);
157	}
158	
159	// 3) custom-lite profile：custom_private 模式下硬约束
160	const profilePath = join(FACTORY, "profiles", "custom-lite.json");
161	const profile = commercial_mode === "custom_private" && existsSync(profilePath)
162	  ? JSON.parse(readFileSync(profilePath, "utf8"))
163	  : null;
164	if (profile) {
165	  const qc = profile.constraints.question_count;
166	  const rc = profile.constraints.result_count;
167	  if (brief.question_count < qc.min || brief.question_count > qc.max)
168	    FAIL(`custom-lite profile 要求 question_count ${qc.min}–${qc.max}，brief 为 ${brief.question_count}。`);
169	  if (brief.result_count < rc.min || brief.result_count > rc.max)
170	    FAIL(`custom-lite profile 要求 result_count ${rc.min}–${rc.max}，brief 为 ${brief.result_count}。`);
171	  if (brief.image_required)
172	    warnings.push("custom-lite 默认不做全套独立 AI 插画；brief.image_required=true 属于围栏外升级，需在 notes 里写明升级依据。");
173	}
174	
175	// 4) 其他语义提醒（不阻断）
176	if (commercial_mode === "internal" && brief.owner_id !== "internal")
177	  warnings.push("commercial_mode=internal 但 owner_id 不是 internal——确认归属是否正确。");
178	if (commercial_mode === "hosted_creator" && !brief.created_for)
179	  warnings.push("hosted_creator 模式建议填写 created_for（客户/创作者标识）。");
180	if (commercial_mode === "hosted_creator" && brief.revenue_share_hint)
181	  warnings.push("revenue_share_hint 仅为记录意图；当前没有分账基础设施，不构成任何承诺。");
182	if (brief.status && brief.status !== "draft")
183	  warnings.push(`新建工作目录的 brief.status 应为 draft（当前 ${brief.status}）。`);
184	
185	/* ------------------------------------------------------------- file writers */
186	const pad = (i) => String(i + 1).padStart(2, "0");
187	const now = new Date().toISOString().slice(0, 10);
188	const skillFor =
189	  commercial_mode === "skill_generated"
190	    ? "factory/skills/SELLABLE_TEST_CREATOR.md"
191	    : "factory/skills/INTERNAL_TEST_FACTORY.md";
192	
193	const resultSlot = (i) => ({
194	  id: `TODO_result_${pad(i)}`,
195	  name: null, subtitle: null, keywords: null, core_energy: null,
196	  inner_conflict: null, relationship_style: null, strengths: null,
197	  blind_spots: null, reading: null,
198	  back_subtitle: null, back_reading: null,
199	  share_line: null, visual_direction: null, character_basis: null, mythic_trace: null,
200	});
201	const questionSlot = (i) => ({
202	  id: `TODO_q${pad(i)}`,
203	  question: null,
204	  options: [{ text: null, scores: {} }, { text: null, scores: {} }, { text: null, scores: {} }],
205	  dimension: null,
206	  editor_note: null,
207	});
208	
209	const files = {};
210	
211	files["brief.json"] = JSON.stringify(
212	  { ...brief, status: "draft", _created: now, _created_by: "factory/create-test.mjs", _schema: "factory/brief.schema.json" },
213	  null, 2
214	) + "\n";
215	
216	files["STATUS.md"] = `# STATUS — ${brief.title}（${product_id}）
217	
218	- commercial_mode: \`${commercial_mode}\` · owner_id: \`${brief.owner_id}\` · language: \`${brief.language}\`
219	- brief: ${briefArg} → 本目录 \`brief.json\`（${now} 由 create-test 生成）
220	- 规格锁定：${brief.question_count} 题 / ${brief.result_count} 结果 / ${brief.result_style} / 插画 ${brief.image_required ? "需要" : "不需要（预设视觉）"}
221	${profile ? "- profile: **custom-lite**（factory/profiles/custom-lite.json 围栏内生产）" : ""}
222	
223	## 阶段状态
224	
225	| 阶段 | 文件 | 状态 |
226	|---|---|---|
227	| S1 结果设计 | result_design.md | TODO |
228	| S2 内容 | questions.json + scoring_spec.md + copy.md | TODO |
229	| S3 视觉 | visual_spec.md${brief.image_required ? " + image_prompts.md" : "（预设视觉，无独立插画）"} | TODO |
230	| S4 QA | qa_report.md | TODO |
231	| S5 发布 | publish_checklist.md | TODO（上线时执行） |
232	
233	## 下一步（给继续的 agent 的协议）
234	
235	1. 先读 \`${skillFor}\`，再读对应阶段 SOP（factory/STAGE_*.md）。
236	2. 按 S1→S5 顺序填本目录文件；只填 TODO / null 处，**不假造任何已完成内容**。
237	3. 每完成一个文件：把上表状态改 DONE，并在文件末尾写一行证据（跑过的校验命令/评审记录）。
238	4. 遇到与 brief 冲突的事实，停下来写进 qa_report.md 的"冲突记录"，不要自行改 brief。
239	
240	## 边界（本产品适用）
241	
242	${commercial_mode === "skill_generated"
243	  ? "- skill_generated：本产品**不在本仓库部署**；产出物按 SELLABLE skill 的交付包规范整理。\n- 不得引用本仓库私有服务器/部署/许可设施。"
244	  : profile
245	    ? "- custom-lite 围栏：预设布局、预设视觉、共享域名、无商业托管权、无独立后端（见 factory/CUSTOM_LITE.md）。"
246	    : "- 走本仓库全流水线：S4 注册 server/content/products/ + deploy；遵守十条铁律（factory/README.md §四）。"}
247	`;
248	
249	files["result_design.md"] = `# S1 结果设计 — ${brief.title}（${brief.result_count} 个原型）
250	
251	> 目标：过 STAGE_1 的 G1 剩余项 + 完成原型区分表。依据 brief：${brief.audience}
252	> 语调约束：${brief.tone.join(" / ")}
253	
254	## 1. 原型区分表（每行必填，两两区分）
255	
256	| # | 结果 id（slug，永不变） | 名称 | 核心能量 core_energy | 内在冲突 inner_conflict | 与相邻原型的区分（一句） |
257	|---|---|---|---|---|---|
258	${Array.from({ length: brief.result_count }, (_, i) => `| ${i + 1} | ${TODO} | ${TODO} | ${TODO} | ${TODO} | ${TODO} |`).join("\n")}
259	
260	## 2. 维度覆盖清单（每题落的维度；同一心理问题不许换皮重问）
261	
262	友谊 / 亲密吸引 / 家庭期待 / 隐私边界 / 孤独与恢复 / 野心与妥协 /
263	尊严与尴尬 / 嫉妒与羡慕 / 变化与不确定 / 归属与独立 / 被误解 / 隐秘愿望
264	
265	## 3. 红线（照抄自 CONTENT_EDITOR_PROMPT.md，不可协商）
266	
267	- 不诊断、不贴标签、不羞辱、不声称科学有效性；
268	- 没有哪个选项明显更聪明/更善良/更成熟；
269	- 每个结果都要"有吸引力也有张力"：没有完美结果，也没有侮辱性结果；
270	- 结果 id 用稳定 slug，永不用显示名做路由键。
271	
272	## 4. 自检（过门条件）
273	
274	- [ ] ${brief.result_count} 个原型两两区分成立（写满区分列）
275	- [ ] 每个原型的冲突结构能支撑 ≥2 道不同维度的题
276	- [ ] 与 brief.notes 声明的差异化一致
277	
278	> 证据：____（完成人/日期/评审一句话）
279	`;
280	
281	files["questions.json"] = JSON.stringify(
282	  {
283	    schema_version: "content-upgrade-1",
284	    status: "draft",
285	    _how_to_fill: [
286	      "本文件是题库骨架：所有 null / TODO 处待填，禁止假造终稿。",
287	      "规程：factory/STAGE_2_CONTENT.md + 仓库根 CONTENT_EDITOR_PROMPT.md（编辑五轴自检 <20 分重写）。",
288	      `题量 ${brief.question_count}、每题恰好 3 个选项；scores 只允许出现 result_design.md 已定的结果 id，权重 0–3 整数（3 主线索 / 1 次线索）`,
289	      "结果对象含双面卡字段（back_subtitle/back_reading），单面卡系列留 null 即可。",
290	      "完成后跑 scoring_spec.md 里的校验命令，再删除 _how_to_fill 与各 TODO 标记，status 改 review。",
291	      `语调约束（来自 brief.tone）: ${brief.tone.join("；")}`,
292	    ],
293	    collection_title: brief.title,
294	    editorial_summary: {
295	      audience: brief.audience,
296	      tone: brief.tone,
297	      design_principles: [],
298	      changes_from_prototype: ["全新生产，无原型；design_principles 在自检通过后回填"],
299	    },
300	    themes: [
301	      {
302	        id: brief.theme,
303	        title: null,
304	        subtitle: null,
305	        disclaimer: "This is a cultural character-style experience, not a scientific personality assessment.",
306	        results: Array.from({ length: brief.result_count }, (_, i) => resultSlot(i)),
307	        questions: Array.from({ length: brief.question_count }, (_, i) => questionSlot(i)),
308	        scoring: { method: null, normalization_bounds: null, tie_break: null, result_order: null },
309	        editorial_review: null,
310	      },
311	    ],
312	  },
313	  null, 2
314	) + "\n";
315	
316	files["scoring_spec.md"] = `# S2 评分规格 — ${product_id}
317	
318	> 真实评分数据（scores/权重/边界）随 questions.json 提交；本文件定**规格**并记录校验证据。
319	
320	## 标准评分模型（与线上产品同构，偏离需说明理由）
321	
322	- 每个选项的 scores 为 0–3 整数：3=主线索，1=次线索；只计最终结果 id，不给中间维度记分；
