readFileState.content:
// Server-side scoring core — ported verbatim from the former frontend implementation
// (deploy-ready/app.js, 2026-09 era) so the algorithm is byte-for-byte the same
// behaviour, now private to the server. The frontend no longer carries any of this.
//
// Implements exactly what each theme's `scoring` block declares:
//   normalised = 100 * (raw - minimum) / (maximum - minimum)
// then a three-level tie-break:
//   1. unrounded normalised score
//   2. share of this archetype's 3-point options that were selected
//   3. declared result_order

export function isScoredQuiz(quiz) {
  return Boolean(quiz && quiz.scoring && quiz.scoring.normalization_bounds);
}

export function rawScores(quiz, answers) {
  const scores = {};
  (quiz.results || []).forEach((result) => { scores[result.id] = 0; });
  (quiz.questions || []).forEach((question, qIndex) => {
    const option = question.options[answers[qIndex]];
    if (!option || !option.scores) return;
    Object.entries(option.scores).forEach(([resultId, points]) => {
      if (Object.prototype.hasOwnProperty.call(scores, resultId)) scores[resultId] += points;
    });
  });
  return scores;
}

export function normalizeScore(raw, bound) {
  if (!bound) return raw;
  const minimum = Number(bound.minimum) || 0;
  const maximum = Number(bound.maximum);
  if (!Number.isFinite(maximum) || maximum === minimum) return raw;
  return (100 * (raw - minimum)) / (maximum - minimum);
}

export function threePointTotals(quiz) {
  const totals = {};
  (quiz.results || []).forEach((result) => { totals[result.id] = 0; });
  (quiz.questions || []).forEach((question) => {
    (question.options || []).forEach((option) => {
      Object.entries(option.scores || {}).forEach(([resultId, points]) => {
        if (points === 3 && Object.prototype.hasOwnProperty.call(totals, resultId)) totals[resultId] += 1;
      });
    });
  });
  return totals;
}

export function selectedThreePointCounts(quiz, answers) {
  const selected = {};
  (quiz.results || []).forEach((result) => { selected[result.id] = 0; });
  (quiz.questions || []).forEach((question, qIndex) => {
    const option = question.options[answers[qIndex]];
    if (!option || !option.scores) return;
    Object.entries(option.scores).forEach(([resultId, points]) => {
      if (points === 3 && Object.prototype.hasOwnProperty.call(selected, resultId)) selected[resultId] += 1;
    });
  });
  return selected;
}

export function selectWinner(quiz, answers) {
  const raw = rawScores(quiz, answers);
  const ids = (quiz.results || []).map((result) => result.id);
  if (!ids.length) return { winnerId: null, ranked: [], scores: raw };
  if (!isScoredQuiz(quiz)) {
    const winnerId = ids.slice().sort((a, b) => raw[b] - raw[a])[0];
    return { winnerId, ranked: ids.slice().sort((a, b) => raw[b] - raw[a]), scores: raw };
  }

  const bounds = quiz.scoring.normalization_bounds;
  const order = quiz.scoring.result_order && quiz.scoring.result_order.length
    ? quiz.scoring.result_order
    : ids;
  const totals = threePointTotals(quiz);
  const selected = selectedThreePointCounts(quiz, answers);

  const ranked = ids.slice().sort((a, b) => {
    const diff = normalizeScore(raw[b], bounds[b]) - normalizeScore(raw[a], bounds[a]);
    if (Math.abs(diff) > 1e-9) return diff;
    const shareA = totals[a] ? selected[a] / totals[a] : 0;
    const shareB = totals[b] ? selected[b] / totals[b] : 0;
    if (Math.abs(shareA - shareB) > 1e-12) return shareB - shareA;
    const orderA = order.indexOf(a);
    const orderB = order.indexOf(b);
    return (orderA === -1 ? ids.indexOf(a) : orderA) - (orderB === -1 ? ids.indexOf(b) : orderB);
  });

  return { winnerId: ranked[0], ranked, scores: raw };
}

// The client only ever submits an index per question; anything else is rejected
// before scoring so a tampered payload cannot reach the matrix.
export function validateAnswers(quiz, answers) {
  const questions = quiz.questions || [];
  if (!Array.isArray(answers)) return "answers must be an array of option indices";
  if (answers.length !== questions.length) {
    return `answers length ${answers.length} does not match ${questions.length} questions`;
  }
  for (let i = 0; i < answers.length; i += 1) {
    const a = answers[i];
    if (!Number.isInteger(a) || a < 0 || a >= questions[i].options.length) {
      return `answers[${i}] is not a valid option index`;
    }
  }
  return null;
}

