"""Audit every display field of the greek-women theme for encoding damage.

Four distinct states are possible for a string in this data set:

  clean      the string round-trips as UTF-8 and is readable
  mojibake   UTF-8 bytes were decoded as latin-1; losslessly recoverable by
             re-encoding to latin-1 and decoding as UTF-8
  lost       every character was replaced by '?' (U+003F); the original text is
             gone and the field must be rewritten from source material
  empty      missing or blank

Run:
    python tools/audit_encoding.py
"""

from __future__ import annotations

import json
import unicodedata
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PATH = ROOT / "server" / "content" / "quiz_content_upgrade.json"  # server-private since the paywall

FIELDS = [
    "name", "subtitle", "keywords", "core_energy", "inner_conflict", "relationship_style",
    "strengths", "blind_spots", "reading", "share_line", "visual_direction",
    "character_basis", "mythic_trace",
]
TEXT_FIELDS = [f for f in FIELDS if f != "keywords"]


def mojibake_fix(value: str) -> str | None:
    """Return the repaired string if `value` is latin-1-decoded UTF-8, else None."""
    try:
        repaired = value.encode("latin-1").decode("utf-8")
    except (UnicodeEncodeError, UnicodeDecodeError):
        return None
    return repaired if repaired != value else None


def cjk_ratio(value: str) -> float:
    if not value:
        return 0.0
    cjk = sum(1 for ch in value if "\u4e00" <= ch <= "\u9fff")
    return cjk / len(value)


def classify(value: object) -> str:
    if value is None or value == "" or value == []:
        return "empty"
    if isinstance(value, list):
        states = {classify(item) for item in value}
        if states == {"clean"}:
            return "clean"
        if "lost" in states:
            return "lost"
        if "mojibake" in states:
            return "mojibake"
        return "clean"
    text = str(value)
    if "?" in text:
        return "lost"
    stripped = text.strip()
    if not stripped:
        return "empty"
    if mojibake_fix(text) is not None:
        return "mojibake"
    # readable Chinese should be mostly CJK
    if cjk_ratio(text) < 0.25 and any(ord(ch) > 0x7F for ch in text):
        return "suspect"
    return "clean"


def main() -> int:
    with PATH.open("r", encoding="utf-8") as handle:
        data = json.load(handle)
    theme = next(t for t in data["themes"] if t["id"] == "greek-women")

    tally: dict[str, list[str]] = {"clean": [], "mojibake": [], "lost": [], "empty": [], "suspect": []}
    print(f"{'result':<11} " + " ".join(f"{f[:9]:>9}" for f in FIELDS))
    for result in theme["results"]:
        cells = []
        for field in FIELDS:
            state = classify(result.get(field))
            tally.setdefault(state, []).append(f"{result['id']}.{field}")
            cells.append(f"{state[:9]:>9}")
        print(f"{result['id']:<11} " + " ".join(cells))

    print()
    for state in ("lost", "mojibake", "empty", "suspect"):
        entries = tally.get(state, [])
        print(f"{state:>9}: {len(entries)}")
        for entry in entries:
            print(f"            {entry}")

    print("\n--- recovery preview ---")
    for entry in tally.get("mojibake", []):
        result_id, field = entry.split(".")
        result = next(r for r in theme["results"] if r["id"] == result_id)
        original = result[field]
        if isinstance(original, list):
            fixed = [mojibake_fix(item) or item for item in original]
        else:
            fixed = mojibake_fix(original) or original
        print(f"  {entry}\n    before: {original!r}\n    after : {fixed!r}")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

