    const probe = await fetch(`/themes/${encodeURIComponent(testId)}/skin.json`, { method: "HEAD" });
    if (!probe.ok) return null;
    const module = await import(`/themes/${encodeURIComponent(testId)}/skin.js`);
    const skin = module && module.default;
    if (!skin || skin.id !== testId || !skin.views) return null;
    injectSkinStylesheet(testId);
    return adoptSkin(skin);
  } catch (error) {
    return null; // 该产品没有皮肤
  }
}

// 皮肤接管了该页面则返回 true。皮肤页面自带 chrome（顶栏属于表达的一部分），
// 所以这里直接写 #app 并标记 body[data-skin]；默认 shell() 会摘掉该标记，
// 保证皮肤未接管的页面（或无皮肤的产品）永远使用默认模板的样式。
function trySkinView(name, ctx) {
  const skin = state.skin;
  if (!skin || !skin.views || typeof skin.views[name] !== "function") return false;
  const view = skin.views[name](ctx);
  const html = view && typeof view.html === "string" ? view.html : "";
  if (!html) return false;
  app.innerHTML = html;
  document.body.setAttribute("data-skin", skin.id || state.testId);
  if (view && typeof view.bind === "function") view.bind(app, ctx);
  return true;
}

/* 皮肤回调上下文：一页一个，只给功能不给表达。返回值语义化，皮肤自行决定
   如何呈现错误与归属提示；引擎的默认渲染函数在开头问一次 trySkinView。 */
function gateContext(message) {
  return {
    message: message || "",
    async submit(rawCode) {
      const code = String(rawCode || "").trim();
      if (!code) return { type: "error", kind: "empty" };
      const stored = getLicense();
      const result = await api("/api/redeem", {
        code, secret: stored ? stored.secret : null, fingerprint: deviceFingerprint()
      });
      if (result.ok && result.data.ok && result.data.secret) {
        saveLicense({ code, secret: result.data.secret });
        if (result.data.product_id !== state.testId) {
          return { type: "other-product", name: result.data.product_name || result.data.product_id };
        }

