"""Encoding audit for any theme content file (parameterized generalization of
tools/audit_encoding.py, which stays greek-specific as a fixed regression).

Classifies every display field of every result as clean / mojibake / lost /
empty / suspect, and fails (exit 1) unless the file is clean.

Usage:
    python tools/audit_encoding_any.py --file server/content/weather_station.json [--theme weather-station]
"""
from __future__ import annotations

import argparse
import json
from pathlib import Path

FIELDS = [
    "name", "subtitle", "keywords", "core_energy", "inner_conflict", "relationship_style",
    "strengths", "blind_spots", "reading", "back_subtitle", "back_reading", "share_line",
    "visual_direction", "character_basis", "mythic_trace",
]


def mojibake_fix(value: str) -> str | None:
    try:
        repaired = value.encode("latin-1").decode("utf-8")
    except (UnicodeEncodeError, UnicodeDecodeError):
        return None
    return repaired if repaired != value else None


def cjk_ratio(value: str) -> float:
    if not value:
        return 0.0
    cjk = sum(1 for ch in value if "\u4e00" <= ch <= "\u9fff")
    return cjk / len(value)


def classify(value: object) -> str:
    if value is None or value == "" or value == []:
        return "empty"
    if isinstance(value, list):
        states = {classify(item) for item in value}
        if "lost" in states:
            return "lost"
        if "mojibake" in states:
            return "mojibake"
        return "clean"
    text = str(value)
    if "?" in text:
        return "lost"
    if not text.strip():
        return "empty"
    if mojibake_fix(text) is not None:
        return "mojibake"
    if cjk_ratio(text) < 0.25 and any(ord(ch) > 0x7F for ch in text):
        return "suspect"
    return "clean"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--file", required=True, help="content JSON path (relative to repo root or absolute)")
    parser.add_argument("--theme", default=None, help="theme id; defaults to the file's first theme")
    args = parser.parse_args()

    path = Path(args.file)
    if not path.is_absolute():
        path = Path(__file__).resolve().parent.parent / args.file
    with path.open("r", encoding="utf-8") as handle:
        data = json.load(handle)

    themes = data["themes"]
    theme = next((t for t in themes if t["id"] == args.theme), None) if args.theme else themes[0]
    if theme is None:
        print(f"✗ theme {args.theme!r} not found in {path}")
        return 1

    tally: dict[str, list[str]] = {}
    print(f"file: {path}\ntheme: {theme['id']} ({len(theme['results'])} results)\n")
    print(f"{'result':<16} " + " ".join(f"{f[:9]:>9}" for f in FIELDS))
    for result in theme["results"]:
        cells = []
        for field in FIELDS:
            state = classify(result.get(field))
            tally.setdefault(state, []).append(f"{result['id']}.{field}")
            cells.append(f"{state[:9]:>9}")
        print(f"{result['id']:<16} " + " ".join(cells))

    bad_states = [s for s in ("lost", "mojibake", "suspect") if tally.get(s)]
    empties = tally.get("empty", [])
    print()
    for state in ("lost", "mojibake", "suspect", "empty"):
        entries = tally.get(state, [])
        print(f"{state:>9}: {len(entries)}")
        for entry in entries:
            print(f"            {entry}")

    if bad_states:
        print(f"\n✗ FAIL: encoding damage detected in {', '.join(bad_states)}")
        return 1
    expected_empty = {"back_subtitle", "back_reading"}  # 单面卡系列允许为空的字段
    unexpected_empty = [e for e in empties if e.split(".", 1)[1] not in expected_empty]
    print(f"\n✓ PASS: clean（empty 仅出现在允许字段: back_subtitle/back_reading）"
          if not unexpected_empty else f"\n✗ FAIL: unexpected empty fields: {unexpected_empty}")
    return 0 if not unexpected_empty else 1


if __name__ == "__main__":
    raise SystemExit(main())

