/* 情绪气象台 —— 产品视觉层样式（station-card 预设视觉族）
 *
 * 作用域：全部规则挂在 body[data-skin="weather-station"] 下，与其他产品
 * 和默认模板完全隔离。
 *
 * 世界观：气象观测所标本卡。米纸底 + 坐标纸细网格、墨青单线边框 + 纸底间隔
 * 形成的双线框签名、等宽字观测戳；七种结果各有专属墨色。与文学皮肤的
 * 缝纫虚线、傲偏的信纸、公主柔光、猫贴纸都不同。
 * 布局沿用手机纵向目标：一页一屏、结果立绘 38dvh、dvh + 安全区。
 */

body[data-skin="weather-station"] {
  --wx-ink: #2F3B42;
  --wx-soft: #6B7680;
  --wx-card: #F7F2E7;
  --wx-paper: #F2ECDF;
  --wx-hairline: rgba(47, 59, 66, 0.45);
  --wx-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;
  --wx-mono: ui-monospace, "SF Mono", "JetBrains Mono", Consolas, monospace;

  margin: 0;
  color: var(--wx-ink);
  font-family: var(--wx-serif);
  background-color: var(--wx-paper);
  background-image:
    repeating-linear-gradient(0deg, transparent 0 27px, rgba(47, 59, 66, 0.05) 27px 28px),
    repeating-linear-gradient(90deg, transparent 0 27px, rgba(47, 59, 66, 0.05) 27px 28px);
}

body[data-skin="weather-station"] .wx {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="weather-station"] .wx-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
  color: var(--wx-soft);
  font: 500 11px/1 var(--wx-mono);
  letter-spacing: .14em;
}

body[data-skin="weather-station"] .wx-brand {
  color: var(--wx-ink);
  font-weight: 700;
  letter-spacing: .12em;
}

body[data-skin="weather-station"] .wx-eyebrow {
  margin: 0 0 10px;
  color: var(--wx-soft);
  font: 600 11px/1 var(--wx-mono);
  letter-spacing: .3em;
  text-transform: uppercase;
}

body[data-skin="weather-station"] .wx-title {
  margin: 6px 0 12px;
  font-size: clamp(27px, 7.4vw, 41px);
  font-weight: 700;
  line-height: 1.5;
  letter-spacing: .02em;
}

body[data-skin="weather-station"] .wx-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--wx-soft);
  font-size: 14.5px;
  line-height: 1.95;
}

body[data-skin="weather-station"] .wx-foot {
  margin: 24px 0 0;
  color: #8B8878;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 卡片 ----
   双线框签名：1.5px 实线 + 4px 纸底间隔 + 1px 发丝线 */
body[data-skin="weather-station"] .wx-card {
  max-width: 460px;
  margin: 0 auto;
  padding: 30px 26px;
  border: 1.5px solid var(--wx-ink);
  border-radius: 2px;
  background: var(--wx-card);
  box-shadow:
    0 0 0 4px var(--wx-paper),
    0 0 0 5px var(--wx-hairline);
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="weather-station"] .wx-btn {
  padding: 13px 44px;
  border: 1.5px solid var(--wx-ink);
  border-radius: 2px;
  background: var(--wx-ink);
  color: var(--wx-paper);
  font: 700 15.5px/1 var(--wx-serif);
  letter-spacing: .22em;
  text-indent: .22em;
  cursor: pointer;
  transition: background-color .18s ease, border-color .18s ease;
}

body[data-skin="weather-station"] .wx-btn:hover { background: #1E282E; border-color: #1E282E; }
body[data-skin="weather-station"] .wx-btn-big { padding: 14px 50px; font-size: 16px; }

body[data-skin="weather-station"] .wx-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1.5px solid rgba(47, 59, 66, .3);
  background: transparent;
  color: var(--wx-soft);
  font: 500 13px/1.5 var(--wx-serif);
  letter-spacing: .1em;
  cursor: pointer;
}

body[data-skin="weather-station"] .wx-link:hover { color: var(--wx-accent, var(--wx-ink)); border-color: var(--wx-accent, var(--wx-ink)); }
body[data-skin="weather-station"] .wx-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入场 ---- */
body[data-skin="weather-station"] .wx-gate { margin-top: 7vh; text-align: center; }

body[data-skin="weather-station"] .wx-gate-lead { margin: 0 0 22px; }

body[data-skin="weather-station"] .wx-gate-form { display: flex; gap: 10px; }

body[data-skin="weather-station"] .wx-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border: 1.5px solid var(--wx-hairline);
  border-radius: 2px;
  background: #FFFDF8;
  color: var(--wx-ink);
  font: 600 14px/1.4 var(--wx-mono);
  letter-spacing: .06em;
}

body[data-skin="weather-station"] .wx-gate-input:focus-visible {
  outline: 0;
  border: 2px solid var(--wx-accent, var(--wx-ink));
}

body[data-skin="weather-station"] .wx-gate .wx-btn { padding: 13px 30px; }

body[data-skin="weather-station"] .wx-gate-error {
  min-height: 20px;
  margin: 12px 0 0;
  color: #A6422E;
  font-size: 13px;
}

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="weather-station"] .wx-cover { margin-top: 4vh; text-align: center; }

body[data-skin="weather-station"] .wx-cast {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 16px 0 4px;
}

body[data-skin="weather-station"] .wx-cast-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1.5px solid var(--wx-hairline);
  transition: transform .16s ease;
}

body[data-skin="weather-station"] .wx-cast-dot:hover { transform: scale(1.22); border-color: var(--wx-ink); }
body[data-skin="weather-station"] .wx-cover-actions { margin: 22px 0 0; }

/* ---------------------------------------------------------------- 答题 ---- */
body[data-skin="weather-station"] .wx-progress {
  height: 6px;
  margin: 2px 2px 14px;
  border: 1px solid var(--wx-hairline);
  background:
    repeating-linear-gradient(90deg, transparent 0 13px, rgba(47, 59, 66, 0.18) 13px 14px);
  overflow: hidden;
}

body[data-skin="weather-station"] .wx-progress i {
  display: block;
  height: 100%;
  background: var(--wx-accent, var(--wx-ink));
  transition: width .3s ease;
