/* 情绪气象台 —— 产品视觉层（product skin，station-card 预设视觉族首用）
 *
 * 世界观：气象观测所标本卡。米纸底、墨青单线 + 纸底间隔双线框、等宽字观测戳、
 * 七种结果各配专属墨色；结果页立绘为手写 SVG 观测卡（assets/weather-station/<id>.svg），
 * 缺图自动退回 ❋ 字符兜底，不出现破图。
 * 结果页（减字定稿）：立绘 → 名字 → share_line → reading → 保存按钮。
 * 皮肤只做表达：评分、题库、网络一律不进本文件。
 */

const SKIN_ID = "weather-station";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

const CAST = [
  { id: "typhoon-eye", name: "台风眼", color: "#B5442E" },
  { id: "plum-rain", name: "梅雨季", color: "#5E7E90" },
  { id: "thunderstorm", name: "雷阵雨", color: "#A65B32" },
  { id: "first-snow", name: "初雪", color: "#7FA1B3" },
  { id: "south-wind", name: "回南天", color: "#8A8272" },
  { id: "partly-cloudy", name: "晴间多云", color: "#C08A3E" },
  { id: "gust", name: "阵风", color: "#33424C" },
];

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (result && result.color) || (cast && cast.color) || "#33424C";
};

function pageShell(inner) {
  return `<div class="wx">${inner}</div>`;
}

function brandBar(right) {
  return `<header class="wx-top"><span class="wx-brand">情绪气象台</span><span class="wx-top-right">${right}</span></header>`;
}

function resultImage(resultId, name, accent) {
  const src = `/assets/weather-station/${encodeURIComponent(resultId)}.svg`;
  return `
    <figure class="wx-portrait" style="--wx-accent:${accent}">
      <img src="${src}" alt="${esc(name || resultId || "天气")}观测卡" loading="eager" decoding="async"
           onerror="this.closest('figure').classList.add('wx-no-art'); this.remove();">
      <span class="wx-fallback" aria-hidden="true">❋</span>
    </figure>`;
}

/* ----------------------------------------------------------- 回执 ---- */
const GATE_ERRORS = {
  empty: "先输入兑换码。",
  already_bound: "这个码已在别的浏览器激活。换设备请联系卖家重置绑定。",
  rate_limited: "尝试太频繁了，稍等一分钟再来。",
  invalid: "兑换码无效，检查一下再试。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("观测入口")}
    <section class="wx-card wx-gate">
      <p class="wx-eyebrow">Weather Station</p>
      <h1 class="wx-title">出示你的兑换码</h1>
      <p class="wx-lead">输入兑换码开始观测。激活后与当前浏览器绑定，之后随时回来。</p>
      <div class="wx-gate-form">
        <input id="wx-gate-code" class="wx-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="wx-btn" id="wx-gate-submit">开始</button>
      </div>
      <p class="wx-gate-error" id="wx-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="wx-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#wx-gate-code");
    const submit = root.querySelector("#wx-gate-submit");
    const error = root.querySelector("#wx-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`这个码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，检查一下再试。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("观测入口")}
    <section class="wx-card wx-cover">
      <p class="wx-eyebrow">Weather Station · 内心天气</p>
      <h1 class="wx-title">你的内心，<br>今天是哪种天气？</h1>
      <p class="wx-lead">${esc(ctx.theme.subtitle)}</p>
      <div class="wx-cast" aria-label="七种天气">
        ${CAST.map((c) => `<span class="wx-cast-dot" style="background:${c.color}" title="${esc(c.name)}"></span>`).join("")}
      </div>
      <div class="wx-cover-actions">
        <button class="wx-btn wx-btn-big" id="wx-start">开始观测</button>
      </div>
      <p class="wx-foot">14 个日常时刻 · 约三分钟 · 原创娱乐测试，不是科学人格测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#wx-start").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 答题 ---- */
function questionView(ctx) {
  const buttons = ctx.options.map((text, i) => `
    <button class="wx-option${ctx.selected === i ? " picked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="wx-option-key" aria-hidden="true">${"ABC"[i] || "•"}</span>
      <span class="wx-option-text">${esc(text)}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`REC ${String(ctx.index + 1).padStart(2, "0")}/${ctx.total}`)}
    <div class="wx-progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${ctx.total}" aria-valuenow="${ctx.index + 1}">
      <i style="width:${Math.round(((ctx.index + 1) / ctx.total) * 100)}%"></i>
    </div>
    <section class="wx-q">
      <p class="wx-q-count">第 ${ctx.index + 1} 次记录 · 共 ${ctx.total} 次</p>
      <h2 class="wx-q-text">${esc(ctx.question)}</h2>
      <div class="wx-options">${buttons}</div>
      <div class="wx-q-nav">
        <button class="wx-link" id="wx-prev" ${ctx.index === 0 ? "disabled" : ""}>← 上一条</button>
        <button class="wx-link" id="wx-exit">先放下</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".wx-option").forEach((option) => {
      option.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        option.classList.add("picked");
        option.setAttribute("aria-pressed", "true");
        window.setTimeout(() => ctx.select(Number(option.dataset.i)), 260);
      });
    });
    const prev = root.querySelector("#wx-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#wx-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* --------------------------------------------------------- 等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("仪器校准中")}
    <section class="wx-card wx-loading">
      <p class="wx-eyebrow">Computing</p>
      <p class="wx-loading-text">正在生成你的观测报告……</p>
      <p class="wx-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* ----------------------------------------------------------- 结果 ---- */
function verdictView(ctx) {
  const result = ctx.result || {};
  const accent = colorOf(result);
  const observationNo = String((CAST.findIndex((c) => c.id === result.id) + 1) || 1).padStart(2, "0");

  const html = pageShell(`
    ${brandBar(`OBS.${observationNo}`)}
    <section class="wx-result" style="--wx-accent:${accent}">
      ${resultImage(result.id, result.name, accent)}
      <div class="wx-name-row">
        <h2 class="wx-name">${esc(result.name || "")}</h2>
      </div>
      ${result.subtitle ? `<p class="wx-quote-source">${esc(result.subtitle)}</p>` : ""}
      ${result.share_line ? `<p class="wx-quote">${esc(result.share_line)}</p>` : ""}
      ${result.reading ? `<p class="wx-reading">${esc(result.reading)}</p>` : ""}

      <div class="wx-save">
        <button class="wx-btn" id="wx-share">保存观测报告</button>
        <div class="wx-minor">
          <button class="wx-link" id="wx-copy">复制文案</button>
          <button class="wx-link" id="wx-again">再测一次</button>
          <button class="wx-link" id="wx-home">回封面</button>
        </div>
      </div>
    </section>`);

  const bind = (root) => {
    const copy = root.querySelector("#wx-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已复制 ✓";
      window.setTimeout(() => { copy.textContent = "复制文案"; }, 1800);
    });
    root.querySelector("#wx-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#wx-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#wx-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享结果图 ----
   观测报告卡：纸底 + 双线框 + 符号 + 观测戳 + 名字 + share_line，全部 Canvas 绘制。 */

function drawGlyph(c, id, cx, cy, s) {
  c.save();
  c.lineWidth = s * 0.09;
  c.strokeStyle = "#2F3B42";
  c.lineCap = "round";
  c.lineJoin = "round";
  if (id === "typhoon-eye") {
    c.strokeStyle = "#B5442E";
    c.beginPath(); c.arc(cx, cy, s * 0.16, 0, Math.PI * 2); c.fillStyle = "#B5442E"; c.fill();
    c.lineWidth = s * 0.06;
    c.beginPath(); c.arc(cx, cy, s * 0.38, 0, Math.PI * 2); c.stroke();
    c.strokeStyle = "#2F3B42";
    c.lineWidth = s * 0.08;
    c.beginPath(); c.arc(cx, cy, s * 0.62, 0, Math.PI * 2); c.stroke();
    c.beginPath(); c.moveTo(cx + s * 0.64, cy - s * 0.42);
    c.quadraticCurveTo(cx + s * 1.05, cy - s * 0.1, cx + s * 0.78, cy + s * 0.6); c.stroke();
    c.beginPath(); c.moveTo(cx - s * 0.64, cy + s * 0.42);
    c.quadraticCurveTo(cx - s * 1.05, cy + s * 0.1, cx - s * 0.78, cy - s * 0.6); c.stroke();
  } else if (id === "plum-rain") {
    c.strokeStyle = "#5E7E90";
    c.lineWidth = s * 0.05;
    for (let i = 0; i < 7; i += 1) {
      const x = cx - s * 0.85 + i * s * 0.28;
      c.beginPath(); c.moveTo(x, cy - s * 0.7); c.lineTo(x - s * 0.06, cy - s * 0.1 + (i % 3) * s * 0.12); c.stroke();
    }
    c.lineWidth = s * 0.06;
    c.beginPath(); c.ellipse(cx - s * 0.35, cy + s * 0.5, s * 0.22, s * 0.045, 0, 0, Math.PI * 2); c.stroke();
    c.beginPath(); c.ellipse(cx + s * 0.3, cy + s * 0.62, s * 0.26, s * 0.05, 0, 0, Math.PI * 2); c.stroke();
  } else if (id === "thunderstorm") {
    c.strokeStyle = "#2F3B42";
    c.lineWidth = s * 0.08;
    c.beginPath();
    c.arc(cx - s * 0.32, cy - s * 0.3, s * 0.22, Math.PI * 0.4, Math.PI * 1.6);
    c.arc(cx, cy - s * 0.42, s * 0.26, Math.PI * 1.1, Math.PI * 1.95);
    c.arc(cx + s * 0.34, cy - s * 0.3, s * 0.2, Math.PI * 1.4, Math.PI * 0.6);
    c.stroke();
    c.strokeStyle = "#A65B32";
    c.lineWidth = s * 0.09;
    c.beginPath();
    c.moveTo(cx + s * 0.08, cy - s * 0.12);
    c.lineTo(cx - s * 0.2, cy + s * 0.25);
    c.lineTo(cx + s * 0.04, cy + s * 0.3);
    c.lineTo(cx - s * 0.24, cy + s * 0.68);
    c.stroke();
  } else if (id === "first-snow") {
    c.strokeStyle = "#7FA1B3";
    c.lineWidth = s * 0.055;
    for (let i = 0; i < 6; i += 1) {
      const a = Math.PI / 3 * i;
      const dx = Math.cos(a), dy = Math.sin(a);
      c.beginPath(); c.moveTo(cx + dx * s * 0.08, cy + dy * s * 0.08); c.lineTo(cx + dx * s * 0.66, cy + dy * s * 0.66); c.stroke();
      for (const r of [0.34, 0.52]) {
        for (const sign of [-1, 1]) {
          const ba = a + sign * Math.PI / 3.2;
          c.beginPath();
          c.moveTo(cx + dx * s * r, cy + dy * s * r);
          c.lineTo(cx + dx * s * r + Math.cos(ba) * s * 0.14, cy + dy * s * r + Math.sin(ba) * s * 0.14);
          c.stroke();
        }
      }
    }
  } else if (id === "south-wind") {
    for (const [i, color] of [["0", "#8A8272"], ["1", "#5E7E90"], ["2", "#8A8272"]]) {
      const y = cy + (Number(i) - 1) * s * 0.3 + s * 0.15;
      c.strokeStyle = color;
      c.lineWidth = s * 0.07;
      c.beginPath();
      c.moveTo(cx - s * 0.8, y);
      for (let x = 0; x <= 8; x += 1) {
        c.quadraticCurveTo(cx - s * 0.8 + (x + 0.5) * s * 0.2, y + (x % 2 ? -1 : 1) * s * 0.07, cx - s * 0.8 + (x + 1) * s * 0.2, y);
      }
      c.stroke();
    }
    c.fillStyle = "#5E7E90";
    c.beginPath(); c.arc(cx + s * 0.12, cy - s * 0.34, s * 0.09, 0, Math.PI * 2); c.fill();
    c.fillStyle = "#8A8272";
    c.beginPath(); c.arc(cx - s * 0.4, cy - s * 0.6, s * 0.06, 0, Math.PI * 2); c.fill();
    c.beginPath(); c.arc(cx + s * 0.5, cy + s * 0.08, s * 0.05, 0, Math.PI * 2); c.fill();
  } else if (id === "partly-cloudy") {
    c.fillStyle = "#C08A3E";
    c.beginPath(); c.arc(cx, cy - s * 0.1, s * 0.52, 0, Math.PI * 2); c.fill();
    c.fillStyle = "#F2ECDF";
    c.strokeStyle = "#5E7E90";
    c.lineWidth = s * 0.07;
    c.beginPath();
    c.arc(cx - s * 0.22, cy + s * 0.3, s * 0.22, Math.PI * 0.5, Math.PI * 1.9);
    c.arc(cx + s * 0.1, cy + s * 0.2, s * 0.26, Math.PI * 1.15, Math.PI * 1.98);
    c.arc(cx + s * 0.4, cy + s * 0.32, s * 0.2, Math.PI * 1.3, Math.PI * 0.55);
    c.closePath();
    c.fill(); c.stroke();
  } else {
    c.strokeStyle = "#2F3B42";
    c.lineWidth = s * 0.1;
    c.beginPath(); c.moveTo(cx - s * 0.9, cy + s * 0.35);
    c.bezierCurveTo(cx - s * 0.2, cy + s * 0.25, cx + s * 0.2, cy + s * 0.1, cx + s * 0.85, cy - s * 0.35); c.stroke();
    c.lineWidth = s * 0.06;
    c.beginPath(); c.moveTo(cx - s * 0.8, cy + s * 0.62);
    c.bezierCurveTo(cx - s * 0.1, cy + s * 0.52, cx + s * 0.3, cy + s * 0.38, cx + s * 0.8, cy + s * 0.02); c.stroke();
    c.lineWidth = s * 0.035;
    c.beginPath(); c.moveTo(cx - s * 0.85, cy + s * 0.82);
    c.bezierCurveTo(cx - s * 0.2, cy + s * 0.74, cx + s * 0.25, cy + s * 0.62, cx + s * 0.6, cy + s * 0.46);
    c.bezierCurveTo(cx + s * 0.78, cy + s * 0.38, cx + s * 0.82, cy + s * 0.28, cx + s * 0.7, cy + s * 0.24); c.stroke();
  }
  c.restore();
}

function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const c = canvas.getContext("2d");
  const accent = colorOf(result);

  c.fillStyle = "#F2ECDF";
  c.fillRect(0, 0, 900, 1200);
  c.strokeStyle = "#2F3B42";
  c.lineWidth = 5;
  c.strokeRect(42, 42, 816, 1116);
  c.lineWidth = 2;
  c.strokeStyle = "rgba(47, 59, 66, 0.45)";
  c.strokeRect(60, 60, 780, 1080);

  const center = (text, y, font, color) => {
    c.font = font;
    c.fillStyle = color;
    c.textAlign = "center";
    c.fillText(text, 450, y);
  };

  c.font = "600 26px 'SF Mono', ui-monospace, Menlo, monospace";
  c.fillStyle = "#6B7680";
  c.textAlign = "center";
  c.fillText("WEATHER STATION · 内心天气观测报告", 450, 130);

  drawGlyph(c, result.id, 450, 400, 420);

  center(result.name || "", 760, "800 78px 'PingFang SC', 'Microsoft YaHei', sans-serif", accent);
  center(result.subtitle || "", 810, "400 30px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#6B7680");

  const shareLine = result.share_line || "";
  c.font = "600 40px 'PingFang SC', 'Microsoft YaHei', sans-serif";
  c.fillStyle = "#2F3B42";
  c.textAlign = "center";
  const rows = wrap(c, shareLine, 680);
  rows.forEach((rowText, i) => c.fillText(rowText, 450, 900 + i * 58));

  CAST.forEach((cast, i) => {
    c.fillStyle = cast.color;
    c.beginPath();
    c.arc(450 - (CAST.length - 1) * 13 + i * 26, 1080, 6, 0, Math.PI * 2);
    c.fill();
  });
  center("结果由答题选择生成 · 原创娱乐测试，不是科学人格测评", 1130, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#8B8878");

  canvas.toBlob((blob) => {
    if (!blob) return;
    const link = document.createElement("a");
    link.download = `weather-station-${result.id || "result"}.png`;
    link.href = URL.createObjectURL(blob);
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
  }, "image/png");
}

function wrap(c, text, maxWidth) {
  const rows = [];
  let current = "";
  for (const ch of String(text || "")) {
    if (c.measureText(current + ch).width > maxWidth) { rows.push(current); current = ch; }
    else current += ch;
  }
  if (current) rows.push(current);
  return rows;
}

export default {
  id: SKIN_ID,
  title: "情绪气象台：你的内心天气观测报告",
  copyText(result) {
    return `${result.name || ""}\n${result.share_line || ""}\n\n来自「情绪气象台」原创娱乐测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
};

