  if (path === "/api/verify-license") {
    if (norm(body.code) === norm(CODE) && body.secret === SECRET && activated) return json(200, { ok: true, product_id: "weather-station", product_name: "情绪气象台：你的内心天气观测报告" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/content") return json(200, SANITIZED);
  if (path === "/api/score") {
    const theme = WX_THEMES.find((t) => t.id === body.theme);
    if (!theme) return json(404, { ok: false, error: "invalid_theme" });
    if (norm(body.code) !== norm(CODE) || body.secret !== SECRET) return json(403, { ok: false, error: "already_bound" });
    const { winnerId } = selectWinner(theme, body.answers);
    const result = theme.results.find((r) => r.id === winnerId);
    lastScoreTheme = theme.id;
    return json(200, { ok: true, winnerId, result });
  }
  throw new Error(`unexpected fetch: ${url}`);
};
function json(status, body) {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}

