const SECRET = "[REDACTED:SECRET_ASSIGNMENT]";
const WX_THEMES = productThemes("weather-station");
const SANITIZED = {
  product: { product_id: "weather-station", name: "情绪气象台：你的内心天气观测报告" },
  themes: WX_THEMES.map(sanitizeTheme),
