function verdictView(ctx) {
  const result = ctx.result || {};
  const id = result.id || "generic";
  const en = (CAST.find((c) => c.id === result.id) || {}).en || "";
  const frontSubtitle = result.subtitle || result.core_energy || "";
  const frontReading = result.reading || result.description || "";
  const backSubtitle = result.back_subtitle || frontSubtitle;
  const backReading = result.back_reading || frontReading;

  const html = pageShell(`
    ${brandBar("这一张")}
    <section class="gg-result" style="--gg-accent:${colorOf(result)}">
      <div class="scene">
        <article class="result-panel result-card flip-card result-${esc(id)}" data-result-id="${esc(id)}" data-result-art="${esc(id)}" role="button" tabindex="0" aria-label="翻转${esc(result.name || "")}结果卡" aria-pressed="false">
          ${resultFace(result, en, "front", frontSubtitle, frontReading)}
          ${resultFace(result, en, "back", backSubtitle, backReading)}
        </article>
      </div>
      <div class="gg-save">
        <button class="gg-btn" id="gg-share">生成分享图</button>
        <div class="gg-minor">
          <button class="gg-link" id="gg-copy">复制文案</button>
          <button class="gg-link" id="gg-again">再测一次</button>
          <button class="gg-link" id="gg-home">返回主题</button>
        </div>
      </div>
      <p class="gg-disclaimer">${esc(ctx.theme.disclaimer || "")}</p>
    </section>`);

  const bind = (root) => {
    /* 缺图兜底：每面独立降级到刻线希腊字母，不出现破图。 */
    root.querySelectorAll("[data-art]").forEach((img) => {
      img.addEventListener("error", () => {
        const face = img.closest(".face");
        if (!face) return;
        face.classList.add("art-missing");
        img.remove();
        const fallback = face.querySelector("[data-art-fallback]");
        if (fallback) fallback.hidden = false;
      });
    });

    /* 翻面 + CARD_MOTION：落卡、两次探视、升力。与默认模板行为一致：
       邀请最多两次之后永远安静；计时器只在真实浏览器排程。 */
    const card = root.querySelector("[data-result-art]");
    const frontFace = card.querySelector(".front");
    const backFace = card.querySelector(".back");
    const media = typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
    const reduceMotion = Boolean(media && media.matches);
    if (Array.isArray(window.__ggCardMotionTimers)) window.__ggCardMotionTimers.forEach(window.clearTimeout);
    window.__ggCardMotionTimers = [];
    const timers = window.__ggCardMotionTimers;

    if (!reduceMotion) {
      card.classList.add("card-arrive");
      card.addEventListener("animationend", function onArrive(event) {
        if (event.animationName !== "card-arrive") return;
        card.classList.remove("card-arrive");
        card.removeEventListener("animationend", onArrive);
      });
    }

    let touched = false;
    const quietInvite = () => {
      touched = true;
      timers.forEach(window.clearTimeout);
    };

    if (media && !reduceMotion) {
      timers.push(window.setTimeout(() => {
        if (touched || !card.isConnected) return;
        card.classList.add("card-peek-1");
      }, 3000));
      timers.push(window.setTimeout(() => {
        if (touched || !card.isConnected) return;
        card.classList.remove("card-peek-1");
        card.classList.add("card-peek-2");
      }, 7500));
    }

    const toggle = () => {
      const isBack = card.classList.toggle("is-back");
      card.setAttribute("aria-pressed", String(isBack));
      card.setAttribute("aria-label", isBack ? "返回结果卡正面" : "翻转结果卡");
      if (frontFace) frontFace.setAttribute("aria-hidden", String(isBack));
      if (backFace) backFace.setAttribute("aria-hidden", String(!isBack));
      if (!touched) quietInvite();
      card.classList.remove("card-peek-1");
      card.classList.remove("card-peek-2");
      card.classList.remove("is-flipping");
      void card.offsetWidth; /* 连续翻面时让升力动画各自重新起步 */
      if (!reduceMotion) card.classList.add("is-flipping");
    };
    card.onclick = toggle;
    card.onkeydown = (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        toggle();
      }
    };

    /* 动作区 */
    const copy = root.querySelector("#gg-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已复制 ✓";
      window.setTimeout(() => { copy.textContent = "复制文案"; }, 1800);
    });
    root.querySelector("#gg-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#gg-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#gg-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享结果图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const c = canvas.getContext("2d");
  const accent = colorOf(result);

  const paper = (withFrame) => {
    c.fillStyle = "#F3EEE2";
    c.fillRect(0, 0, 900, 1200);
    c.strokeStyle = "#232E3A";
    c.lineWidth = 5;
    c.strokeRect(42, 42, 816, 1116);
    c.lineWidth = 2;
    c.strokeStyle = "rgba(35, 46, 58, 0.4)";
    c.strokeRect(60, 60, 780, 1080);
    if (withFrame) {
      c.fillStyle = "#A6472F";
      [[74, 74], [826, 74], [74, 1126], [826, 1126]].forEach(([x, y]) => {
        c.beginPath(); c.arc(x, y, 5, 0, Math.PI * 2); c.fill();
      });
    }
  };

  const center = (text, y, font, color) => {
    c.font = font;
    c.fillStyle = color;
    c.textAlign = "center";
    c.fillText(text, 450, y);
  };

  paper(true);
  center("MYTHIC · 希腊女神测试", 128, "600 28px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#6E6A5E");

  const img = new Image();
  img.onload = () => {
    const w = 470;
    const h = (img.height / img.width) * w;
    const x = (900 - w) / 2;
    const y = 170;
    c.save();
    c.strokeStyle = "#232E3A";
    c.lineWidth = 4;
    c.strokeRect(x - 6, y - 6, w + 12, h + 12);
    c.drawImage(img, x, y, w, h);
    c.restore();
    finish(y + h + 96);
  };
  img.onerror = () => finish(560);

  function finish(top) {
    const en = (CAST.find((cast) => cast.id === result.id) || {}).en || "";
    center(result.name || "", top, "800 76px 'Songti SC', 'PingFang SC', sans-serif", accent);
    if (en) center(en, top + 44, "400 26px Georgia, serif", "#6E6A5E");
    const line = result.share_line || result.subtitle || "";
    c.font = "600 36px 'PingFang SC', 'Microsoft YaHei', sans-serif";
    c.fillStyle = "#232E3A";
    c.textAlign = "center";
    const rows = wrap(c, line, 660);
    rows.forEach((rowText, i) => c.fillText(rowText, 450, top + 108 + i * 54));

    CAST.forEach((cast, i) => {
      c.fillStyle = cast.color;
      c.beginPath();
      c.arc(450 - (CAST.length - 1) * 13 + i * 26, 1080, 6, 0, Math.PI * 2);
      c.fill();
    });
    center("结果由答题选择生成 · 原创演绎，非神话立场 · 非科学人格测评", 1130, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#8D8672");

    canvas.toBlob((blob) => {
      if (!blob) return;
      const link = document.createElement("a");
      link.download = `greek-${result.id || "result"}.png`;
      link.href = URL.createObjectURL(blob);
      link.click();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    }, "image/png");
  }
}

function wrap(c, text, maxWidth) {
  const rows = [];
  let current = "";
  for (const ch of String(text || "")) {
    if (c.measureText(current + ch).width > maxWidth) { rows.push(current); current = ch; }
    else current += ch;
  }
  if (current) rows.push(current);
  return rows;
}

