const CODE = "GGSMOKETEST0001";
const SECRET = "[REDACTED:SECRET_ASSIGNMENT]";
const GG_THEMES = productThemes("greek_goddess");
const SANITIZED = {
  product: { product_id: "greek_goddess", name: "希腊女神测试" },
  themes: GG_THEMES.map(sanitizeTheme),
};
let activated = false;
let lastScoreTheme = null;
globalThis.fetch = async (url, options = {}) => {
  const body = options.body ? JSON.parse(options.body) : {};
  const norm = (c) => String(c || "").toUpperCase().replace(/[\s-]+/g, "");
  const path = String(url).split("?")[0];
  if (path === "/api/redeem") {
    if (norm(body.code) !== norm(CODE)) return json(404, { ok: false, error: "invalid_code" });
    if (!activated) {
      activated = true;
      return json(200, { ok: true, secret: SECRET, firstUse: true, product_id: "greek_goddess", product_name: "希腊女神测试" });
    }
    if (body.secret === SECRET) return json(200, { ok: true, secret: SECRET, firstUse: false, product_id: "greek_goddess", product_name: "希腊女神测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/verify-license") {
    if (norm(body.code) === norm(CODE) && body.secret === SECRET && activated) return json(200, { ok: true, product_id: "greek_goddess", product_name: "希腊女神测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/content") return json(200, SANITIZED);
  if (path === "/api/score") {
    const theme = GG_THEMES.find((t) => t.id === body.theme);
    if (!theme) return json(404, { ok: false, error: "invalid_theme" });
    if (norm(body.code) !== norm(CODE) || body.secret !== SECRET) return json(403, { ok: false, error: "already_bound" });
    const { winnerId } = selectWinner(theme, body.answers);
    const result = theme.results.find((r) => r.id === winnerId);
    lastScoreTheme = theme.id;
    return json(200, { ok: true, winnerId, result });
  }
  throw new Error(`unexpected fetch: ${url}`);
};
function json(status, body) {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}

