/* 希腊女神测试（旗舰）· 陶绘皮肤端到端流程测试。
 *
 * 真实 deploy-ready/app.js + 真实 themes/greek_goddess/skin.js 驱动完整流程：
 * 入场（兑换码）→ 封面（12 位女神）→ 24 题作答 → 服务端评分（真实 server/scoring.mjs）
 * → 双面结果卡（翻面 + 键盘 + 缺图兜底 + flavor 类）→ 分享/复制/重测。
 * 另附 12 结果可达性采样与跨产品隔离检查。
 *
 * Run: node tools/test-greek-skin.mjs
 */
import { readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { selectWinner } from "../server/scoring.mjs";
import { sanitizeTheme } from "../server/sanitize.mjs";
import { productThemes } from "../server/products.mjs";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const results = [];
const check = (name, fn) => {
  try {
    const d = fn();
    if (d && typeof d.then === "function") {
      return d.then((detail) => results.push({ ok: true, name, d: detail }),
        (e) => results.push({ ok: false, name, d: e.message }));
    }
    results.push({ ok: true, name, d });
  } catch (e) {
    results.push({ ok: false, name, d: e.message });
  }
  return Promise.resolve();
};
const assert = (c, m) => { if (!c) throw new Error(m); };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* --------------------------------------------------------- DOM 桩 ---- */
const VOID = new Set(["br", "hr", "img", "input", "meta", "link", "area", "base", "col", "embed", "source", "track", "wbr"]);

function parseFragment(html) {
  const root = new El("#fragment");
  const stack = [root];
  const tokenRe = /<\/?([a-zA-Z][a-zA-Z0-9-]*)((?:\s+[a-zA-Z-]+(?:\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+))?)*)\s*(\/?)>|([^<]+)/g;
  let m;
  while ((m = tokenRe.exec(html))) {
    if (m[4] !== undefined) {
      if (m[4].trim()) stack[stack.length - 1].children.push(m[4]);
      continue;
    }
    const tag = m[1].toLowerCase();
    if (html[m.index + 1] === "/") {
      for (let i = stack.length - 1; i > 0; i -= 1) {
        if (stack[i].tagName === tag.toUpperCase()) { stack.length = i; break; }
      }
      continue;
    }
    const el = new El(tag);
    const attrRe = /([a-zA-Z-]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?/g;
    let a;
    while ((a = attrRe.exec(m[2] || ""))) {
      const name = a[1].toLowerCase();
      const value = a[2] ?? a[3] ?? a[4] ?? "";
      el.attributes[name] = value;
      if (name === "id") el.id = value;
      if (name === "class") String(value).split(/\s+/).filter(Boolean).forEach((c) => el.classList.add(c));
      if (name.startsWith("data-")) el.dataset[name.slice(5).replace(/-([a-z])/g, (_, ch) => ch.toUpperCase())] = value;
    }
    stack[stack.length - 1].children.push(el);
    el.parent = stack[stack.length - 1];
    if (!VOID.has(tag) && m[3] !== "/") stack.push(el);
  }
  return root.children;
}

function matchesSelector(el, selector) {
  const parts = selector.trim().split(/\s+/);
  if (parts.length > 1) {
    const last = parts[parts.length - 1];
    if (!matchesSelector(el, last)) return false;
    let node = el.parent;
    let depth = parts.length - 2;
    while (node && depth >= 0) {
      if (matchesSelector(node, parts[depth])) depth -= 1;
      node = node.parent;
    }
    return depth < 0;
  }
  const m = selector.match(/^([a-zA-Z][\w-]*)?((?:[.#][\w-]+)*)$/) || selector.match(/^\[([a-zA-Z-]+)\]$/);
  if (!m) throw new Error(`stub selector unsupported: ${selector}`);
  if (selector.startsWith("[")) {
    return el.attributes[selector.slice(1, -1)] !== undefined;
  }
  if (m[1] && el.tagName !== m[1].toUpperCase()) return false;
  const tokens = (m[2] || "").match(/[.#][\w-]+/g) || [];
  for (const part of tokens) {
    if (part[0] === "#") { if (el.id !== part.slice(1)) return false; }
    else if (!el.classList.contains(part.slice(1))) return false;
  }
  return true;
}

class El {
  constructor(tag) {
    this.tagName = tag.toUpperCase();
    this.id = "";
    this.children = [];
    this.attributes = {};
    this.dataset = {};
    this.listeners = {};
    this._cls = new Set();
    this.style = {};
    this.value = "";
    this.hidden = false;
    this.parent = null;
    this.classList = {
      add: (...names) => names.forEach((n) => this._cls.add(n)),
      remove: (...names) => names.forEach((n) => this._cls.delete(n)),
      contains: (n) => this._cls.has(n),
    };
  }
  set innerHTML(html) { this.children = parseFragment(html); }
  get innerHTML() { return this.children.map((c) => (typeof c === "string" ? c : c.outer)).join(""); }
  get outer() { return `<${this.tagName.toLowerCase()}>${this.innerHTML}</${this.tagName.toLowerCase()}>`; }
  get textContent() { return this.children.map((c) => (typeof c === "string" ? c : c.textContent)).join(""); }
  set textContent(v) { this.children = [String(v)]; }
  setAttribute(n, v) { this.attributes[n] = String(v); if (n === "id") this.id = String(v); }
  getAttribute(n) { return this.attributes[n] ?? null; }
  removeAttribute(n) { delete this.attributes[n]; }
  addEventListener(t, fn) { (this.listeners[t] ||= []).push(fn); }
  dispatch(type, event = {}) { (this.listeners[type] || []).forEach((fn) => fn({ ...event, target: this })); }
  click() { this.dispatch("click"); }
  focus() {}
  querySelector(sel) { return this.querySelectorAll(sel)[0] || null; }
  querySelectorAll(sel) {
    const out = [];
    const walk = (el) => {
      for (const child of el.children) {
        if (typeof child !== "string") {
          if (matchesSelector(child, sel)) out.push(child);
          walk(child);
        }
      }
    };
    walk(this);
    return out;
  }
  appendChild(child) { this.children.push(child); child.parent = this; return child; }
}

/* --------------------------------------------------- 浏览器全局桩 ---- */
const appEl = new El("main");
appEl.id = "app";
const docEl = new El("#document");
docEl.appendChild(appEl);
const bodyEl = new El("body");
docEl.appendChild(bodyEl);
const headEl = new El("head");
docEl.appendChild(headEl);

const storage = new Map();
globalThis.localStorage = {
  getItem: (k) => (storage.has(k) ? storage.get(k) : null),
  setItem: (k, v) => storage.set(k, String(v)),
  removeItem: (k) => storage.delete(k),
};
let canvasCreated = 0;
globalThis.document = Object.assign(docEl, {
  body: bodyEl,
  head: headEl,
  title: "",
  createElement: (tag) => {
    const el = new El(tag);
    if (tag === "canvas") {
      canvasCreated += 1;
      el.getContext = () => new Proxy({}, {
        get: (t, prop) => {
          if (prop === "measureText") return () => ({ width: 10 });
          return () => {};
        },
      });
      el.toBlob = (cb) => cb(null);
    }
    if (tag === "a") { el.click = () => {}; }
    return el;
  },
});
globalThis.location = { pathname: "/t/greek_goddess", search: "" };
Object.defineProperty(globalThis, "navigator", {
  value: {
    userAgent: "gg-test", language: "zh-CN", platform: "test",
    clipboard: { writeText: async () => {} },
  },
  configurable: true,
});
globalThis.screen = { width: 390, height: 844, colorDepth: 24 };
globalThis.window = globalThis;
globalThis.Image = class { set src(v) { this._src = v; if (this.onload) setTimeout(this.onload, 0); } };

/* ----------------------------------------------------- API 桩 ---- */
const CODE = "GGSMOKETEST0001";
const SECRET = "[REDACTED:SECRET_ASSIGNMENT]";
const GG_THEMES = productThemes("greek_goddess");
const SANITIZED = {
  product: { product_id: "greek_goddess", name: "希腊女神测试" },
  themes: GG_THEMES.map(sanitizeTheme),
};
let activated = false;
let lastScoreTheme = null;
globalThis.fetch = async (url, options = {}) => {
  const body = options.body ? JSON.parse(options.body) : {};
  const norm = (c) => String(c || "").toUpperCase().replace(/[\s-]+/g, "");
  const path = String(url).split("?")[0];
  if (path === "/api/redeem") {
    if (norm(body.code) !== norm(CODE)) return json(404, { ok: false, error: "invalid_code" });
    if (!activated) {
      activated = true;
      return json(200, { ok: true, secret: SECRET, firstUse: true, product_id: "greek_goddess", product_name: "希腊女神测试" });
    }
    if (body.secret === SECRET) return json(200, { ok: true, secret: SECRET, firstUse: false, product_id: "greek_goddess", product_name: "希腊女神测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/verify-license") {
    if (norm(body.code) === norm(CODE) && body.secret === SECRET && activated) return json(200, { ok: true, product_id: "greek_goddess", product_name: "希腊女神测试" });
    return json(403, { ok: false, error: "already_bound" });
  }
  if (path === "/api/content") return json(200, SANITIZED);
  if (path === "/api/score") {
    const theme = GG_THEMES.find((t) => t.id === body.theme);
    if (!theme) return json(404, { ok: false, error: "invalid_theme" });
    if (norm(body.code) !== norm(CODE) || body.secret !== SECRET) return json(403, { ok: false, error: "already_bound" });
    const { winnerId } = selectWinner(theme, body.answers);
    const result = theme.results.find((r) => r.id === winnerId);
    lastScoreTheme = theme.id;
    return json(200, { ok: true, winnerId, result });
  }
  throw new Error(`unexpected fetch: ${url}`);
};
function json(status, body) {
  return { ok: status >= 200 && status < 300, status, json: async () => body };
}

/* --------------------------------------------- 挂载真实皮肤并启动 ---- */
const skinModule = await import(pathToFileURL(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js")).href);
globalThis.__MYTHIC_SKINS__ = { "greek_goddess": skinModule.default };

const appSource = readFileSync(join(ROOT, "deploy-ready", "app.js"), "utf8");
new Function("module", "exports", appSource)({ exports: {} }, {});
await sleep(80);

const skinCss = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.css"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the greek_goddess skin, not the default gate", () => {
  assert(appEl.querySelector(".gg-title"), "greek gate title missing");
  assert(appEl.querySelector(".gg-gate-form"), "gate form missing");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
  assert(bodyEl.attributes["data-skin"] === "greek_goddess", "body data-skin not set");
  assert(globalThis.document.title === "你与哪位希腊神话女性，共享一段心事？", `skin title wrong: ${globalThis.document.title}`);
  return "entrance";
});

await check("a valid code unlocks the cover with the 12-goddess cast row", async () => {
  const input = appEl.querySelector("#gg-gate-code");
  const submit = appEl.querySelector("#gg-gate-submit");
  input.value = CODE.toLowerCase();
  submit.click();
  await sleep(120);
  assert(appEl.querySelector(".gg-cover"), "cover missing after redeem");
  assert(appEl.querySelector(".gg-cover .gg-title").textContent.includes("共享一段心事"), "cover title wrong");
  assert(appEl.querySelectorAll(".gg-cast-dot").length === 12, "cast row must show 12 goddesses");
  assert(appEl.querySelector("#gg-start"), "start button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
  return "cover";
});

await check("starting shows question 1 of 24 with three options and a progress bar", async () => {
  appEl.querySelector("#gg-start").click();
  await sleep(80);
  assert(appEl.querySelector(".gg-q-count").textContent.includes("01 / 24"), `expected Q1, got ${appEl.querySelector(".gg-q-count")?.textContent}`);
  assert(appEl.querySelectorAll(".gg-option").length === 3, "three options expected");
  assert(appEl.querySelector(".gg-progress i"), "progress bar missing");
  return "Q1";
});

await check("picking an option colors it and advances, back restores the pick", async () => {
  appEl.querySelectorAll(".gg-option")[1].click();
  await sleep(60);
  assert(appEl.querySelectorAll(".gg-option")[1].classList.contains("picked"), "option must be picked before advancing");
  await sleep(340);
  assert(appEl.querySelector(".gg-q-count").textContent.includes("02 / 24"), "did not advance to Q2");
  appEl.querySelector("#gg-prev").click();
  await sleep(50);
  assert(appEl.querySelector(".gg-q-count").textContent.includes("01 / 24"), "上一题 failed");
  assert(appEl.querySelectorAll(".gg-option")[1].classList.contains("picked"), "returning must show the recorded pick");
  return "pick + back";
});

await check("a full 24-question run lands on the dual-face result card", async () => {
  for (let i = 0; i < 24; i += 1) {
    const count = appEl.querySelector(".gg-q-count");
    assert(count, `question ${i + 1} missing`);
    appEl.querySelectorAll(".gg-option")[0].click();
    await sleep(340);
  }
  const card = appEl.querySelector("[data-result-art]");
  assert(card, "flip card missing");
  const front = card.querySelector(".face.front");
  const back = card.querySelector(".face.back");
  assert(front && back, "dual faces missing");
  const frontImg = front.querySelector("img");
  assert(frontImg && String(frontImg.attributes.src).startsWith("/assets/greek-women/"), `front art path wrong: ${frontImg?.attributes.src}`);
  assert(String(frontImg.attributes.src).endsWith("-front.webp"), "front art must be the webp portrait");
  const backImg = back.querySelector("img");
  assert(backImg && String(backImg.attributes.src).endsWith("-back.webp"), "back art path wrong");
  const eyebrow = card.querySelector(".face.front .eyebrow");
  assert(eyebrow, "name block missing");
  const reading = card.querySelector(".face.front .reading");
  assert(reading && reading.textContent.trim().length > 20, "front reading missing");
  const backCopy = card.querySelector(".face.back h2") || card.querySelector(".face.back .reading");
  assert(backCopy, "back copy missing");
  for (const id of ["#gg-share", "#gg-copy", "#gg-again", "#gg-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  return `女神：${eyebrow.textContent.trim()}`;
});

await check("flipping works by click and keyboard with correct aria state", async () => {
  const card = appEl.querySelector("[data-result-art]");
  assert(card, "card missing");
  assert(!card.classList.contains("is-back"), "card must start front");
  card.click();
  await sleep(30);
  assert(card.classList.contains("is-back"), "click flip failed");
  assert(card.attributes["aria-pressed"] === "true", "aria-pressed not updated");
  assert(card.attributes["aria-label"] === "返回结果卡正面", "aria-label not updated");
  card.dispatch("keydown", { key: "Enter" });
  await sleep(30);
  assert(!card.classList.contains("is-back"), "keyboard flip back failed");
  card.dispatch("keydown", { key: " " });
  await sleep(30);
  assert(card.classList.contains("is-back"), "space flip failed");
  card.click();
  await sleep(30);
  assert(!card.classList.contains("is-back"), "final restore failed");
  return "flip: click + Enter + Space";
});

await check("the card carries the per-goddess flavor hook", () => {
  const card = appEl.querySelector("[data-result-art]");
  const id = card.attributes["data-result-id"];
  assert(card.classList.contains(`result-${id}`), `flavor class result-${id} missing`);
  assert(/^(athena|aphrodite|artemis|hecate|persephone|demeter|medea|atalanta|hera|hestia|nike|circe)$/.test(id), `unexpected result id ${id}`);
  return `flavor: result-${id}`;
});

await check("share and copy actions work inside the skin", async () => {
  canvasCreated = 0;
  appEl.querySelector("#gg-share").click();
  appEl.querySelector("#gg-copy").click();
  await sleep(60);
  const copy = appEl.querySelector("#gg-copy");
  assert(copy.textContent.includes("已复制"), `copy feedback wrong: ${copy.textContent}`);
  assert(canvasCreated >= 1, "share must build a canvas image");
  return "share + copy";
});

await check("again restarts at Q1, exit returns to the cover", async () => {
  appEl.querySelector("#gg-again").click();
  await sleep(60);
  assert(appEl.querySelector(".gg-q-count").textContent.includes("01 / 24"), "再测一次 failed");
  appEl.querySelector("#gg-exit").click();
  await sleep(60);
  assert(appEl.querySelector(".gg-cover"), "返回主题 failed");
  return "again + exit";
});

await check("scoring went through the server-side declared model", () => {
  assert(lastScoreTheme === "greek-women", "score API was not called with the greek-women theme");
  const theme = GG_THEMES[0];
  assert(theme.scoring && theme.scoring.normalization_bounds, "theme must declare the normalized scoring model");
  return `theme ${lastScoreTheme} scored server-side`;
});

/* ------------------------------------------------------- 可达性 ---- */
check("all 12 goddesses are reachable under the real scoring algorithm", () => {
  const theme = GG_THEMES[0];
  const ids = theme.results.map((r) => r.id);
  assert(ids.length === 12, `expected 12 results, got ${ids.length}`);
  const runs = 200;
  let seed = 84848;
  const rand = () => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed / 0x7fffffff;
  };
  for (const id of ids) {
    let wins = 0;
    for (let run = 0; run < runs; run += 1) {
      const answers = theme.questions.map((question) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < 0.8) return topOptions[Math.floor(rand() * topOptions.length)];
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
      if (run === 0) {
        const full = theme.questions.map((question) =>
          question.options
            .map((o, i) => ({ i, s: o.scores[id] || 0 }))
            .sort((a, b) => b.s - a.s)[0].i);
        const verdict = selectWinner(theme, full);
        assert(verdict.winnerId === id, `full-leaning run elects ${verdict.winnerId} for ${id}`);
      }
    }
    const rate = wins / runs;
    assert(rate >= 0.5, `${id} leaning win-rate ${(rate * 100).toFixed(1)}% < 50%`);
  }
  return "12/12 reachable";
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped and does not touch other products", () => {
  const stripped = skinCss.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") && opens === 1) {
      if (!/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  assert(depth === 0, "unbalanced braces in skin.css");
  for (const foreign of ["lw-", "wx-", "pp-", "dp-", "cat-", "ggw-"]) {
    assert(!skinCss.includes(foreign), `skin.css must not reference ${foreign} (cross-product leak)`);
  }
  return "scoped, no cross-product selectors";
});

check("skin classes used by skin.js all exist in skin.css or are canonical hooks", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js"), "utf8");
  const used = new Set(
    [...js.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/))
      .flatMap((c) => c.match(/gg-[a-z0-9-]+/g) || [])
  );
  const hooks = new Set(["gg-top-right", "gg-option-text", "gg-q"]);
  const defined = new Set([...skinCss.matchAll(/\.(gg-[a-z0-9-]+)/g)].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c) && !hooks.has(c));
  assert(missing.length === 0, `classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js"), "utf8");
  for (const banned of ["normalization_bounds", "selectWinner", "quiz_content_upgrade", "fetch("]) {
    assert(!js.includes(banned), `skin must not contain ${banned}`);
  }
  return "expression only";
});

check("the skin reuses the canonical flip-card structure and motion classes", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js"), "utf8");
  for (const hook of ["flip-card", "card-arrive", "card-peek-1", "is-flipping", "art-missing"]) {
    assert(js.includes(hook), `must reuse ${hook} from the canonical motion system`);
  }
  const css = readFileSync(join(ROOT, "deploy-ready", "styles.css"), "utf8");
  for (const keyframe of ["card-arrive", "card-peek-1", "card-peek-2", "card-flip-lift"]) {
    assert(css.includes(`@keyframes ${keyframe}`), `styles.css lost ${keyframe}`);
  }
  return "canonical structure + global motion intact";
});

check("the product manifest still owns the shared greek content", () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", "greek_goddess", "product.json"), "utf8"));
  assert(manifest.product_id === "greek_goddess", "product id mismatch");
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "quiz_content_upgrade.json"), "utf8"));
  const theme = raw.themes.find((t) => t.id === "greek-women");
  assert(theme, "greek-women theme missing from shared content");
  assert(theme.questions.length === 24, "24 questions");
  assert(theme.results.length === 12, "12 results");
  assert(!appSource.includes("gg-"), "default templates must not reference gg- classes");
  return "own theme, shared matrix";
});

delete globalThis.__MYTHIC_SKINS__;

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n希腊女神（旗舰）陶绘皮肤 · 流程测试\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
process.exit(failures.length ? 1 : 0);

