}
.before .face { transition: transform .7s cubic-bezier(.2,.7,.2,1); }""")

# B 卡：face 过渡（bezier 回退在前，linear() 弹簧在后覆盖；升力动画）
s = s.replace("""  transition: transform .62s linear(
      0, 0.298 12.5%, 0.684 25%, 0.994 37.5%, 1.136 50%,
      1.078 62.5%, 0.993 75%, 1.004 87.5%, 1);
  position: relative;
}""",
"""  position: relative;
}
.after .face { transition: transform .62s cubic-bezier(.3,1.26,.44,1); }
.after .face { transition: transform .62s linear(
      0, 0.298 12.5%, 0.684 25%, 0.994 37.5%, 1.136 50%,
      1.078 62.5%, 0.993 75%, 1.004 87.5%, 1); }""")

# 升力关键帧 + is-flipping
s = s.replace(""".hint { text-align: center;""",
"""/* 翻面升力：物体离桌再落回（两端各自弹簧/平滑） */
@keyframes lift-a {
  0% { transform: translateY(0) scale(1); }
  45% { transform: translateY(-9px) scale(1.012); }
  100% { transform: translateY(0) scale(1); }
}
.flip.is-flipping { animation: lift-a .62s cubic-bezier(.2,.7,.2,1) 1; }
.hint { text-align: center;""")

# JS：翻面时挂升力类
s = s.replace("""  const toggle = () => card.classList.toggle("is-back");""",
"""  const toggle = () => {
    card.classList.toggle("is-back");
    card.classList.remove("is-flipping");
    void card.offsetWidth;
    card.classList.add("is-flipping");
  };
  card.addEventListener("animationend", (e) => {
    if (e.animationName === "lift-a") card.classList.remove("is-flipping");
  });""")

open(p, 'w', encoding='utf8').write(s)
print('fixed:', 'transition: transform .7s cubic-bezier(.2,.7,.2,1); }' not in s and s.count('transition: transform .62s') >= 2)
EOF

